function run_real_data_validation(makePlots)
% EKF replay on held-out recorded-flight windows using shared observations.
% Requires data/real_data_validation generated by Python validate_real_data.py.
% Parameter selection happened only on the development window. No retuning here.
if nargin<1, makePlots=true; end
root=fileparts(fileparts(mfilename('fullpath')));
dataFolder=fullfile(root,'data','real_data_validation');
plan=jsondecode(fileread(fullfile(dataFolder,'manifest.json')));
cases=plan.cases;
for i=1:numel(cases)
    c=cases(i); cfg=tracking_config(); cfg.q=c.q;
    cfg.seed=plan.seed_for_shared_cases; % observations were generated in Python
    D=readtable(fullfile(dataFolder,c.measurements));
    E=readtable(fullfile(dataFolder,c.expected));
    t=D.t_s;
    truth=D{:,{'px_m','py_m','pz_m','vx_mps','vy_mps','vz_mps'}};
    z=D{:,{'range_m','azimuth_rad','elevation_rad'}};
    out=run_filters(t,z,cfg);
    actual=[t out.ekf out.ekf_nis]; expected=E{:,:};
    assert(isequal(size(actual),size(expected)), 'Replay reference shape mismatch.');
    assert(isequal(isnan(actual),isnan(expected)), 'Replay NaN mask mismatch.');
    mask=isfinite(expected);
    errors=abs(actual(mask)-expected(mask));
    assert(all(errors<=1e-7+1e-8*abs(expected(mask))), 'Replay Python/MATLAB parity failed.');
    [metrics,nees]=evaluate_tracking(truth,z,out,cfg);
    label=sprintf('%s_%04ds_q%g',c.flight,c.segment_start_s,c.q);
    folder=fullfile(root,'results','matlab','real_data_validation',label);
    if ~exist(folder,'dir'), mkdir(folder); end
    T=array2table(actual,'VariableNames',{'t_s','ekf_px','ekf_py','ekf_pz', ...
        'ekf_vx','ekf_vy','ekf_vz','ekf_nis'});
    writetable(T,fullfile(folder,'estimates.csv'));
    writetable(struct2table(metrics),fullfile(folder,'metrics.csv'));
    save(fullfile(folder,'run.mat'),'cfg','t','truth','z','out','metrics','nees');
    if makePlots
        figs=plot_tracking(t,truth,z,out,cfg,'replay');
        saveas(figs(1),fullfile(folder,'trajectory_3d.png'));
        saveas(figs(2),fullfile(folder,'errors_nis.png'));
        close(figs(1)); close(figs(2));
    end
    fprintf('%s: shared-observation parity PASS (max difference %.3g), position RMSE %.2f m.\n', ...
        label,max(errors),metrics.ekf_position_rmse_m);
end
fprintf('Recorded-flight validation finished: %d EKF configurations.\n',numel(cases));
end
